zh-to-en.css:
.card {
  text-align: center;
  font-size: 17px;
  line-height: 1.6;
}
.uc-ask {
  margin-bottom: 14px;
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  opacity: 0.55;
}
.uc-simp {
  font-family: var(--han, "Noto Sans SC", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif);
  font-size: 46px;
  font-weight: 400;
  line-height: 1.15;
}
.uc-trad {
  font-family: var(--han, "Noto Sans SC", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif);
  margin-top: 8px;
  font-size: 34px;
  font-weight: 400;
  line-height: 1.25;
  opacity: 0.5;
}
.uc-pinyin {
  margin-top: 12px;
  font-size: 21px;
  letter-spacing: 0.01em;
  opacity: 0.85;
}
.uc-zhuyin {
  font-family: var(--han, "Noto Sans SC", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif);
  margin-top: 5px;
  font-size: 17px;
  letter-spacing: 0.06em;
  opacity: 0.72;
}
.uc-mw {
  margin-top: 12px;
  font-size: 15px;
  line-height: 1.5;
}
.uc-mwlab {
  margin-right: 8px;
  font-size: 9.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  opacity: 0.5;
}
.uc-mwi + .uc-mwi {
  margin-left: 12px;
}
.uc-mwc {
  font-family: var(--han, "Noto Sans SC", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif);
  font-weight: 400;
}
.uc-mwt {
  margin-left: 4px;
  opacity: 0.5;
}
.uc-mwp {
  margin-left: 6px;
  opacity: 0.75;
}
.uc-field {
  display: inline-block;
  max-width: 100%;
  margin-top: 14px;
  padding: 11px 15px;
  border: 1px solid var(--rule, rgba(0,0,0,0.12));
  border-radius: 11px;
  text-align: left;
  background: var(--paper-2, rgba(0,0,0,0.05));
  background: color-mix(in srgb, var(--paper-2, #EFEDE6) 58%, var(--card, #FFFFFF));
}
.uc-sense {
  line-height: 1.6;
}
.uc-sense + .uc-sense {
  margin-top: 2px;
}
hr {
  margin: 18px 0;
  border: 0;
  border-top: 1px solid currentColor;
  opacity: 0.18;
}
.uc-sense {
  font-size: 16px;
}
